import os
from pathlib import Path

def grep(pattern, root='/repo', glob_filter='*.py', max_results=50):
    """Search for pattern in files."""
    results = []
    for f in walk(root):
        if glob_filter and not f.endswith(glob_filter.replace('*', '')):
            continue
        try:
            content = Path(f).read_text()
            for i, line in enumerate(content.split('\n'), 1):
                if re.search(pattern, line):
                    results.append((f, i, line.strip()))
                    if len(results) >= max_results:
                        return results
        except Exception:
            pass
    return results

